-- 0007_commerce_content_ops.sql -- Payments, coupons, referrals, reviews, tickets, blog, portfolio, design styles, monitoring, -- private/secret settings, checkout + admin RPCs, public settings allow-list, receipts bucket. -- Already applied to the live database and tested end to end (checkout, coupon, card-to-card -- approval, renewal, gateway paid/failed, referral reward, RLS, privilege checks). -- Idempotent: safe to commit to drizzle/migrations and replay on a fresh database. -- Requires earlier migrations: app_role, has_role(_user_id, _role), bots, profiles, orders, licenses, site_settings, user_roles. -- ===================== enums ===================== do $$ begin create type public.payment_method as enum ('gateway', 'card_to_card'); exception when duplicate_object then null; end $$; do $$ begin create type public.payment_status as enum ('initiated', 'awaiting_review', 'paid', 'failed', 'rejected', 'refunded'); exception when duplicate_object then null; end $$; do $$ begin create type public.coupon_kind as enum ('percent', 'fixed'); exception when duplicate_object then null; end $$; do $$ begin create type public.moderation_status as enum ('pending', 'approved', 'rejected'); exception when duplicate_object then null; end $$; do $$ begin create type public.ticket_status as enum ('open', 'answered', 'closed'); exception when duplicate_object then null; end $$; -- ===================== settings & delivery ===================== create table if not exists public.private_settings ( key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now() ); -- secret_settings has RLS on and NO policies: only the service role (server functions) can read it. create table if not exists public.secret_settings ( key text primary key, value text not null, updated_at timestamptz not null default now() ); create table if not exists public.product_delivery ( bot_id uuid primary key references public.bots(id) on delete cascade, install_url text, note_fa text, note_en text, updated_at timestamptz not null default now() ); -- ===================== commerce ===================== create table if not exists public.coupons ( id uuid primary key default gen_random_uuid(), code text not null, kind public.coupon_kind not null, value integer not null check (value > 0), max_uses integer check (max_uses is null or max_uses > 0), used_count integer not null default 0, per_user_limit integer not null default 1 check (per_user_limit > 0), min_amount bigint not null default 0, starts_at timestamptz, expires_at timestamptz, active boolean not null default true, bot_ids uuid[], owner_id uuid references auth.users(id) on delete cascade, note text, created_at timestamptz not null default now(), constraint coupons_percent_range check (kind <> 'percent' or value <= 100) ); create unique index if not exists coupons_code_key on public.coupons (upper(code)); create table if not exists public.payments ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, method public.payment_method not null, status public.payment_status not null default 'initiated', subtotal bigint not null check (subtotal >= 0), discount_amount bigint not null default 0 check (discount_amount >= 0), amount bigint not null check (amount >= 0), coupon_id uuid references public.coupons(id) on delete set null, gateway_provider text, gateway_authority text, gateway_ref text, receipt_path text, receipt_reference text, payer_note text, admin_note text, paid_at timestamptz, reviewed_by uuid references auth.users(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now() ); create index if not exists payments_user_idx on public.payments (user_id); create index if not exists payments_status_idx on public.payments (status); create table if not exists public.coupon_redemptions ( id uuid primary key default gen_random_uuid(), coupon_id uuid not null references public.coupons(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, payment_id uuid not null references public.payments(id) on delete cascade, amount_off bigint not null, created_at timestamptz not null default now(), unique (coupon_id, payment_id) ); create index if not exists coupon_redemptions_user_idx on public.coupon_redemptions (coupon_id, user_id); alter table public.orders add column if not exists payment_id uuid references public.payments(id) on delete set null; alter table public.orders add column if not exists unit_price bigint check (unit_price is null or unit_price >= 0); alter table public.orders add column if not exists discount_amount bigint not null default 0 check (discount_amount >= 0); alter table public.orders add column if not exists admin_note text; create index if not exists orders_payment_id_idx on public.orders (payment_id); alter table public.profiles add column if not exists referral_code text not null default upper(substr(md5(gen_random_uuid()::text), 1, 8)); alter table public.profiles add column if not exists referred_by uuid references auth.users(id) on delete set null; create unique index if not exists profiles_referral_code_key on public.profiles (referral_code); create table if not exists public.referrals ( id uuid primary key default gen_random_uuid(), referrer_id uuid not null references auth.users(id) on delete cascade, referred_id uuid not null unique references auth.users(id) on delete cascade, created_at timestamptz not null default now(), rewarded_at timestamptz, reward_coupon_id uuid references public.coupons(id) on delete set null ); create index if not exists referrals_referrer_idx on public.referrals (referrer_id); -- ===================== content, support, monitoring ===================== create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at := now(); return new; end $$; create table if not exists public.reviews ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, bot_id uuid not null references public.bots(id) on delete cascade, rating smallint not null check (rating between 1 and 5), body text not null check (char_length(body) between 3 and 2000), status public.moderation_status not null default 'pending', created_at timestamptz not null default now(), unique (user_id, bot_id) ); create index if not exists reviews_bot_idx on public.reviews (bot_id, status); create table if not exists public.tickets ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, order_id uuid references public.orders(id) on delete set null, subject text not null check (char_length(subject) between 3 and 200), status public.ticket_status not null default 'open', created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create index if not exists tickets_user_idx on public.tickets (user_id); create index if not exists tickets_status_idx on public.tickets (status); create table if not exists public.ticket_messages ( id uuid primary key default gen_random_uuid(), ticket_id uuid not null references public.tickets(id) on delete cascade, author_id uuid not null references auth.users(id) on delete cascade, is_staff boolean not null default false, body text not null check (char_length(body) between 1 and 4000), created_at timestamptz not null default now() ); create index if not exists ticket_messages_ticket_idx on public.ticket_messages (ticket_id, created_at); create or replace function public.ticket_message_before() returns trigger language plpgsql security definer set search_path = public as $$ begin new.is_staff := public.has_role(new.author_id, 'admin'::public.app_role); return new; end $$; create or replace function public.ticket_message_after() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.tickets set updated_at = now(), status = case when new.is_staff then 'answered'::public.ticket_status else 'open'::public.ticket_status end where id = new.ticket_id and status <> 'closed'; return new; end $$; drop trigger if exists ticket_messages_before on public.ticket_messages; create trigger ticket_messages_before before insert on public.ticket_messages for each row execute function public.ticket_message_before(); drop trigger if exists ticket_messages_after on public.ticket_messages; create trigger ticket_messages_after after insert on public.ticket_messages for each row execute function public.ticket_message_after(); create table if not exists public.blog_posts ( id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title_fa text not null, title_en text not null default '', excerpt_fa text not null default '', excerpt_en text not null default '', body_fa text not null default '', body_en text not null default '', cover_url text, published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); drop trigger if exists blog_posts_touch on public.blog_posts; create trigger blog_posts_touch before update on public.blog_posts for each row execute function public.touch_updated_at(); create table if not exists public.portfolio_items ( id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title_fa text not null, title_en text not null default '', desc_fa text not null default '', desc_en text not null default '', kind text not null default 'other' check (kind in ('bot', 'website', 'other')), image_url text, link text, published boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now() ); create table if not exists public.design_styles ( id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title_fa text not null, title_en text not null default '', desc_fa text not null default '', desc_en text not null default '', preview_url text, published boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now() ); create table if not exists public.service_heartbeats ( name text primary key, status text not null default 'ok' check (status in ('ok', 'warn', 'down')), message text, meta jsonb not null default '{}'::jsonb, last_seen timestamptz not null default now() ); create table if not exists public.notification_log ( id uuid primary key default gen_random_uuid(), kind text not null, ref_id uuid, status text not null check (status in ('sent', 'failed', 'skipped')), error text, created_at timestamptz not null default now() ); -- ===================== RLS ===================== alter table public.private_settings enable row level security; alter table public.secret_settings enable row level security; alter table public.product_delivery enable row level security; alter table public.coupons enable row level security; alter table public.payments enable row level security; alter table public.coupon_redemptions enable row level security; alter table public.referrals enable row level security; alter table public.reviews enable row level security; alter table public.tickets enable row level security; alter table public.ticket_messages enable row level security; alter table public.blog_posts enable row level security; alter table public.portfolio_items enable row level security; alter table public.design_styles enable row level security; alter table public.service_heartbeats enable row level security; alter table public.notification_log enable row level security; -- admin: full access (policy name: "admin manages <table>") do $$ declare t text; begin foreach t in array array['private_settings','product_delivery','coupons','payments','coupon_redemptions','referrals', 'reviews','tickets','ticket_messages','blog_posts','portfolio_items','design_styles','service_heartbeats','notification_log'] loop execute format('drop policy if exists "admin manages %1$s" on public.%1$I', t); execute format('create policy "admin manages %1$s" on public.%1$I for all to authenticated using (public.has_role(auth.uid(), ''admin''::public.app_role)) with check (public.has_role(auth.uid(), ''admin''::public.app_role))', t); end loop; end $$; drop policy if exists "own payments read" on public.payments; create policy "own payments read" on public.payments for select to authenticated using (user_id = auth.uid()); drop policy if exists "own referrals read" on public.referrals; create policy "own referrals read" on public.referrals for select to authenticated using (referrer_id = auth.uid() or referred_id = auth.uid()); drop policy if exists "own reviews read" on public.reviews; create policy "own reviews read" on public.reviews for select to authenticated using (user_id = auth.uid()); drop policy if exists "buyers insert pending review" on public.reviews; create policy "buyers insert pending review" on public.reviews for insert to authenticated with check ( user_id = auth.uid() and status = 'pending' and exists (select 1 from public.orders o where o.user_id = auth.uid() and o.bot_id = reviews.bot_id and o.status in ('paid', 'delivered')) ); drop policy if exists "own reviews delete" on public.reviews; create policy "own reviews delete" on public.reviews for delete to authenticated using (user_id = auth.uid()); drop policy if exists "own tickets read" on public.tickets; create policy "own tickets read" on public.tickets for select to authenticated using (user_id = auth.uid()); drop policy if exists "own tickets insert" on public.tickets; create policy "own tickets insert" on public.tickets for insert to authenticated with check (user_id = auth.uid() and status = 'open'); drop policy if exists "own tickets close" on public.tickets; create policy "own tickets close" on public.tickets for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and status = 'closed'); drop policy if exists "own ticket messages read" on public.ticket_messages; create policy "own ticket messages read" on public.ticket_messages for select to authenticated using (exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id and t.user_id = auth.uid())); drop policy if exists "own ticket messages insert" on public.ticket_messages; create policy "own ticket messages insert" on public.ticket_messages for insert to authenticated with check ( author_id = auth.uid() and exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id and t.user_id = auth.uid() and t.status <> 'closed') ); drop policy if exists "public reads published posts" on public.blog_posts; create policy "public reads published posts" on public.blog_posts for select to anon, authenticated using (published); drop policy if exists "public reads published portfolio" on public.portfolio_items; create policy "public reads published portfolio" on public.portfolio_items for select to anon, authenticated using (published); drop policy if exists "public reads published styles" on public.design_styles; create policy "public reads published styles" on public.design_styles for select to anon, authenticated using (published); -- ===================== grants ===================== revoke all on public.secret_settings from anon, authenticated; revoke all on public.private_settings, public.product_delivery, public.coupons, public.payments, public.coupon_redemptions, public.referrals, public.reviews, public.tickets, public.ticket_messages, public.service_heartbeats, public.notification_log from anon; grant select, insert, update, delete on public.private_settings, public.product_delivery, public.coupons, public.payments, public.coupon_redemptions, public.referrals, public.reviews, public.ticket_messages, public.service_heartbeats, public.notification_log, public.blog_posts, public.portfolio_items, public.design_styles to authenticated; grant select, insert, delete on public.tickets to authenticated; grant update (status) on public.tickets to authenticated; grant select on public.blog_posts, public.portfolio_items, public.design_styles to anon; grant all on public.private_settings, public.secret_settings, public.product_delivery, public.coupons, public.payments, public.coupon_redemptions, public.referrals, public.reviews, public.tickets, public.ticket_messages, public.blog_posts, public.portfolio_items, public.design_styles, public.service_heartbeats, public.notification_log to service_role; -- column-level limits: users cannot set price fields on orders or touch referral columns on profiles revoke insert on public.orders from authenticated; grant insert (user_id, type, bot_id, plan_months, details, status) on public.orders to authenticated; revoke update on public.profiles from authenticated; grant update (display_name) on public.profiles to authenticated; -- ===================== functions ===================== create or replace function public._require_admin() returns void language plpgsql stable set search_path = public as $$ begin if not public.has_role(auth.uid(), 'admin'::public.app_role) then raise exception 'not authorized' using errcode = '42501'; end if; end $$; create or replace function public.quote_cart(items jsonb, coupon_code text default null) returns jsonb language plpgsql stable security definer set search_path = public as $$ declare uid uuid := auth.uid(); it jsonb; b public.bots; m int; price bigint; lines jsonb := '[]'::jsonb; seen uuid[] := '{}'; subtotal bigint := 0; eligible bigint := 0; discount bigint := 0; c public.coupons; cmsg text := null; cid uuid := null; user_uses int; v_code text := nullif(btrim(coalesce(coupon_code, '')), ''); begin if uid is null then raise exception 'login required' using errcode = '28000'; end if; if items is null or jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 or jsonb_array_length(items) > 20 then raise exception 'invalid cart' using errcode = '22023'; end if; for it in select * from jsonb_array_elements(items) loop m := (it->>'plan_months')::int; if m not in (1, 3, 6, 12) then raise exception 'invalid plan' using errcode = '22023'; end if; select * into b from public.bots where id = (it->>'bot_id')::uuid and published; if not found then raise exception 'product unavailable' using errcode = '22023'; end if; if b.id = any(seen) then raise exception 'duplicate product' using errcode = '22023'; end if; seen := seen || b.id; price := case m when 1 then b.price_1 when 3 then b.price_3 when 6 then b.price_6 else b.price_12 end; if price is null or price <= 0 then raise exception 'plan has no price' using errcode = '22023'; end if; lines := lines || jsonb_build_array(jsonb_build_object('bot_id', b.id, 'plan_months', m, 'unit_price', price, 'title_fa', b.title_fa, 'title_en', b.title_en)); subtotal := subtotal + price; end loop; if v_code is not null then select * into c from public.coupons cp where upper(cp.code) = upper(v_code); if not found or not c.active or (c.owner_id is not null and c.owner_id <> uid) then cmsg := 'invalid'; elsif c.starts_at is not null and c.starts_at > now() then cmsg := 'not_started'; elsif c.expires_at is not null and c.expires_at <= now() then cmsg := 'expired'; elsif c.max_uses is not null and c.used_count >= c.max_uses then cmsg := 'exhausted'; elsif subtotal < c.min_amount then cmsg := 'min_amount'; else select count(*) into user_uses from public.coupon_redemptions r where r.coupon_id = c.id and r.user_id = uid; if user_uses >= c.per_user_limit then cmsg := 'already_used'; else if c.bot_ids is null then eligible := subtotal; else select coalesce(sum((l->>'unit_price')::bigint), 0) into eligible from jsonb_array_elements(lines) l where (l->>'bot_id')::uuid = any(c.bot_ids); end if; if eligible <= 0 then cmsg := 'not_applicable'; else discount := case c.kind when 'percent' then floor(eligible::numeric * c.value / 100)::bigint else least(c.value::bigint, eligible) end; cid := c.id; cmsg := 'ok'; end if; end if; end if; end if; return jsonb_build_object('lines', lines, 'subtotal', subtotal, 'discount', discount, 'total', subtotal - discount, 'coupon_id', cid, 'coupon_message', cmsg); end $$; create or replace function public._release_payment(p_payment uuid, p_status public.payment_status, p_reviewer uuid default null, p_note text default null) returns void language plpgsql security definer set search_path = public as $$ declare p public.payments; begin select * into p from public.payments where id = p_payment for update; if not found then raise exception 'payment not found' using errcode = '22023'; end if; if p.status in ('paid', 'refunded') then raise exception 'payment already settled' using errcode = '22023'; end if; if p.status in ('failed', 'rejected') then return; end if; update public.payments set status = p_status, reviewed_by = p_reviewer, reviewed_at = case when p_reviewer is not null then now() else reviewed_at end, admin_note = coalesce(p_note, admin_note) where id = p_payment; update public.orders set status = 'cancelled' where payment_id = p_payment and status = 'pending'; if p.coupon_id is not null then with d as (delete from public.coupon_redemptions where payment_id = p_payment returning 1) update public.coupons set used_count = greatest(used_count - (select count(*) from d), 0) where id = p.coupon_id; end if; end $$; create or replace function public._mark_paid(p_payment uuid, p_reviewer uuid default null) returns void language plpgsql security definer set search_path = public as $$ declare p public.payments; o public.orders; lic public.licenses; ref public.referrals; new_exp timestamptz; deliver text; cfg jsonb; ccode text; cid uuid; had_paid boolean; begin select * into p from public.payments where id = p_payment for update; if not found then raise exception 'payment not found' using errcode = '22023'; end if; if p.status = 'paid' then return; end if; if p.status in ('failed', 'rejected', 'refunded') then raise exception 'payment not payable' using errcode = '22023'; end if; update public.payments set status = 'paid', paid_at = now(), reviewed_by = p_reviewer, reviewed_at = case when p_reviewer is not null then now() else null end where id = p_payment; for o in select * from public.orders where payment_id = p_payment and type = 'subscription' and status in ('pending', 'paid') order by created_at loop update public.orders set status = 'paid' where id = o.id; select * into lic from public.licenses where user_id = o.user_id and bot_id = o.bot_id and status in ('active', 'expired') order by expires_at desc limit 1 for update; if found then new_exp := greatest(now(), lic.expires_at) + make_interval(months => o.plan_months); update public.licenses set expires_at = new_exp, status = 'active', plan_months = o.plan_months, order_id = o.id where id = lic.id; else select install_url into deliver from public.product_delivery where bot_id = o.bot_id; insert into public.licenses (order_id, user_id, bot_id, plan_months, starts_at, expires_at, install_url, status) values (o.id, o.user_id, o.bot_id, o.plan_months, now(), now() + make_interval(months => o.plan_months), deliver, 'active'); end if; update public.orders set status = 'delivered' where id = o.id; end loop; select exists (select 1 from public.payments x where x.user_id = p.user_id and x.status = 'paid' and x.id <> p_payment) into had_paid; select * into ref from public.referrals r where r.referred_id = p.user_id and r.rewarded_at is null; if found and not had_paid then select value into cfg from public.private_settings where key = 'referral'; if coalesce((cfg->>'enabled')::boolean, false) then ccode := 'REF-' || upper(substr(md5(gen_random_uuid()::text), 1, 8)); insert into public.coupons (code, kind, value, max_uses, per_user_limit, expires_at, owner_id, note) values (ccode, coalesce((cfg->>'kind')::public.coupon_kind, 'percent'), coalesce((cfg->>'value')::int, 10), 1, 1, now() + make_interval(days => coalesce((cfg->>'expires_days')::int, 90)), ref.referrer_id, 'referral reward') returning id into cid; update public.referrals set rewarded_at = now(), reward_coupon_id = cid where id = ref.id; end if; end if; end $$; create or replace function public.create_checkout(items jsonb, coupon_code text default null, method public.payment_method default 'card_to_card') returns jsonb language plpgsql security definer set search_path = public as $$ declare uid uuid := auth.uid(); opts jsonb; q jsonb; pid uuid; oid uuid; first_order uuid; line jsonb; sub bigint; disc bigint; total bigint; cid uuid; line_price bigint; line_disc bigint; allocated bigint := 0; has_coupon boolean := nullif(btrim(coalesce(coupon_code, '')), '') is not null; cc public.coupons; begin if uid is null then raise exception 'login required' using errcode = '28000'; end if; select value into opts from public.private_settings where key = case method when 'gateway' then 'gateway' else 'card_to_card' end; if coalesce((opts->>'enabled')::boolean, false) is not true then raise exception 'payment method disabled' using errcode = '22023'; end if; if method = 'gateway' and not exists (select 1 from public.secret_settings where key = 'gateway_merchant_id') then raise exception 'payment method disabled' using errcode = '22023'; end if; q := public.quote_cart(items, coupon_code); if has_coupon and (q->>'coupon_message') is distinct from 'ok' then raise exception 'coupon %', coalesce(q->>'coupon_message', 'invalid') using errcode = '22023'; end if; sub := (q->>'subtotal')::bigint; disc := (q->>'discount')::bigint; total := (q->>'total')::bigint; cid := nullif(q->>'coupon_id', '')::uuid; if cid is not null then select * into cc from public.coupons where id = cid for update; if cc.max_uses is not null and cc.used_count >= cc.max_uses then raise exception 'coupon exhausted' using errcode = '22023'; end if; end if; insert into public.payments (user_id, method, status, subtotal, discount_amount, amount, coupon_id, gateway_provider) values (uid, method, 'initiated', sub, disc, total, cid, case when method = 'gateway' then (select value->>'provider' from public.private_settings where key = 'gateway') end) returning id into pid; for line in select * from jsonb_array_elements(q->'lines') loop line_price := (line->>'unit_price')::bigint; line_disc := case when sub > 0 then floor(line_price::numeric * disc / sub)::bigint else 0 end; insert into public.orders (user_id, type, bot_id, plan_months, status, payment_id, unit_price, discount_amount) values (uid, 'subscription', (line->>'bot_id')::uuid, (line->>'plan_months')::int, 'pending', pid, line_price, line_disc) returning id into oid; if first_order is null then first_order := oid; end if; allocated := allocated + line_disc; end loop; if disc > allocated then update public.orders set discount_amount = discount_amount + (disc - allocated) where id = first_order; end if; if cid is not null then insert into public.coupon_redemptions (coupon_id, user_id, payment_id, amount_off) values (cid, uid, pid, disc); update public.coupons set used_count = used_count + 1 where id = cid; end if; if total = 0 then perform public._mark_paid(pid, null); end if; return jsonb_build_object('payment_id', pid, 'amount', total, 'method', method, 'status', (select status from public.payments where id = pid)); end $$; create or replace function public.submit_card_receipt(p_payment uuid, p_path text, p_reference text default null, p_note text default null) returns void language plpgsql security definer set search_path = public as $$ declare p public.payments; begin select * into p from public.payments where id = p_payment and user_id = auth.uid() for update; if not found then raise exception 'payment not found' using errcode = '22023'; end if; if p.method <> 'card_to_card' or p.status <> 'initiated' then raise exception 'payment is not awaiting a receipt' using errcode = '22023'; end if; if p_path is null or split_part(p_path, '/', 1) <> auth.uid()::text then raise exception 'invalid receipt path' using errcode = '22023'; end if; update public.payments set receipt_path = p_path, receipt_reference = left(p_reference, 100), payer_note = left(p_note, 500), status = 'awaiting_review' where id = p_payment; end $$; create or replace function public.cancel_payment(p_payment uuid) returns void language plpgsql security definer set search_path = public as $$ declare p public.payments; begin select * into p from public.payments where id = p_payment and user_id = auth.uid(); if not found then raise exception 'payment not found' using errcode = '22023'; end if; if p.status <> 'initiated' then raise exception 'payment cannot be cancelled' using errcode = '22023'; end if; perform public._release_payment(p_payment, 'failed', null, null); end $$; create or replace function public.admin_review_payment(p_payment uuid, p_approve boolean, p_note text default null) returns void language plpgsql security definer set search_path = public as $$ begin perform public._require_admin(); if p_approve then perform public._mark_paid(p_payment, auth.uid()); if p_note is not null then update public.payments set admin_note = p_note where id = p_payment; end if; else perform public._release_payment(p_payment, 'rejected', auth.uid(), p_note); end if; end $$; create or replace function public.gateway_mark_paid(p_payment uuid, p_authority text, p_ref text) returns void language plpgsql security definer set search_path = public as $$ begin update public.payments set gateway_authority = coalesce(gateway_authority, p_authority), gateway_ref = p_ref where id = p_payment and method = 'gateway'; if not found then raise exception 'gateway payment not found' using errcode = '22023'; end if; perform public._mark_paid(p_payment, null); end $$; create or replace function public.gateway_mark_failed(p_payment uuid) returns void language plpgsql security definer set search_path = public as $$ begin perform public._release_payment(p_payment, 'failed', null, null); end $$; create or replace function public.get_checkout_options() returns jsonb language plpgsql stable security definer set search_path = public as $$ declare c jsonb; g jsonb; c_on boolean; g_on boolean; begin if auth.uid() is null then raise exception 'login required' using errcode = '28000'; end if; select value into c from public.private_settings where key = 'card_to_card'; select value into g from public.private_settings where key = 'gateway'; c_on := coalesce((c->>'enabled')::boolean, false); g_on := coalesce((g->>'enabled')::boolean, false) and exists (select 1 from public.secret_settings where key = 'gateway_merchant_id'); return jsonb_build_object( 'card_to_card', jsonb_build_object( 'enabled', c_on, 'cards', case when c_on then coalesce(c->'cards', '[]'::jsonb) else '[]'::jsonb end, 'instructions_fa', case when c_on then c->>'instructions_fa' end, 'instructions_en', case when c_on then c->>'instructions_en' end), 'gateway', jsonb_build_object('enabled', g_on, 'provider', case when g_on then g->>'provider' end)); end $$; create or replace function public.get_public_reviews(p_bot uuid, p_limit int default 20) returns table (id uuid, rating smallint, body text, author_name text, created_at timestamptz) language sql stable security definer set search_path = public as $$ select r.id, r.rating, r.body, case when coalesce(p.display_name, '') = '' then 'â€¢â€¢â€¢' else left(p.display_name, 1) || 'â€¢â€¢â€¢' end, r.created_at from public.reviews r left join public.profiles p on p.id = r.user_id where r.bot_id = p_bot and r.status = 'approved' order by r.created_at desc limit least(greatest(coalesce(p_limit, 20), 1), 50); $$; create or replace function public.bot_rating_summary(p_bot uuid) returns table (review_count bigint, average_rating numeric) language sql stable security definer set search_path = public as $$ select count(*), coalesce(round(avg(rating)::numeric, 2), 0) from public.reviews where bot_id = p_bot and status = 'approved'; $$; create or replace function public.claim_referral(p_code text) returns boolean language plpgsql security definer set search_path = public as $$ declare uid uuid := auth.uid(); rid uuid; begin if uid is null then raise exception 'login required' using errcode = '28000'; end if; select id into rid from public.profiles where referral_code = upper(btrim(coalesce(p_code, ''))); if rid is null or rid = uid then return false; end if; if exists (select 1 from public.profiles where id = uid and referred_by is not null) then return false; end if; if exists (select 1 from public.payments where user_id = uid and status = 'paid') then return false; end if; update public.profiles set referred_by = rid where id = uid; insert into public.referrals (referrer_id, referred_id) values (rid, uid) on conflict (referred_id) do nothing; return true; end $$; create or replace function public.my_referral_summary() returns jsonb language plpgsql stable security definer set search_path = public as $$ declare uid uuid := auth.uid(); begin if uid is null then raise exception 'login required' using errcode = '28000'; end if; return ( select jsonb_build_object( 'code', p.referral_code, 'referred_count', (select count(*) from public.referrals r where r.referrer_id = uid), 'rewards', coalesce(( select jsonb_agg(jsonb_build_object('coupon_code', c.code, 'kind', c.kind, 'value', c.value, 'used', c.used_count >= coalesce(c.max_uses, 1), 'expires_at', c.expires_at) order by c.created_at desc) from public.coupons c where c.owner_id = uid), '[]'::jsonb)) from public.profiles p where p.id = uid); end $$; create or replace function public.admin_set_secret(p_key text, p_value text) returns void language plpgsql security definer set search_path = public as $$ begin perform public._require_admin(); if p_key not in ('gateway_merchant_id', 'telegram_bot_token', 'heartbeat_token') then raise exception 'unknown secret key' using errcode = '22023'; end if; if p_value is null or btrim(p_value) = '' then delete from public.secret_settings where key = p_key; else insert into public.secret_settings (key, value, updated_at) values (p_key, btrim(p_value), now()) on conflict (key) do update set value = excluded.value, updated_at = now(); end if; end $$; create or replace function public.admin_secret_status() returns table (key text, is_set boolean, hint text, updated_at timestamptz) language plpgsql stable security definer set search_path = public as $$ begin perform public._require_admin(); return query select k.k, s.key is not null, case when s.key is null then null when length(s.value) >= 12 then 'â€¢â€¢â€¢â€¢' || right(s.value, 4) else 'â€¢â€¢â€¢â€¢' end, s.updated_at from (values ('gateway_merchant_id'), ('telegram_bot_token'), ('heartbeat_token')) as k(k) left join public.secret_settings s on s.key = k.k; end $$; create or replace function public.admin_system_status() returns jsonb language plpgsql stable security definer set search_path = public as $$ begin perform public._require_admin(); return jsonb_build_object( 'now', now(), 'users', (select count(*) from auth.users), 'orders_pending', (select count(*) from public.orders where status = 'pending'), 'payments_awaiting_review', (select count(*) from public.payments where status = 'awaiting_review'), 'tickets_open', (select count(*) from public.tickets where status = 'open'), 'reviews_pending', (select count(*) from public.reviews where status = 'pending'), 'licenses_active', (select count(*) from public.licenses where status = 'active' and expires_at > now()), 'licenses_expiring_7d', (select count(*) from public.licenses where status = 'active' and expires_at > now() and expires_at <= now() + interval '7 days'), 'gateway_ready', coalesce((select (value->>'enabled')::boolean from public.private_settings where key = 'gateway'), false) and exists (select 1 from public.secret_settings where key = 'gateway_merchant_id'), 'notify_ready', coalesce((select (value->>'enabled')::boolean from public.private_settings where key = 'notify'), false) and exists (select 1 from public.secret_settings where key = 'telegram_bot_token'), 'heartbeats', coalesce((select jsonb_agg(jsonb_build_object('name', h.name, 'status', h.status, 'message', h.message, 'last_seen', h.last_seen) order by h.name) from public.service_heartbeats h), '[]'::jsonb)); end $$; create or replace function public.admin_sales_summary(p_from date, p_to date, p_bucket text default 'day') returns table (bucket date, payments_count bigint, revenue bigint) language plpgsql stable security definer set search_path = public as $$ begin perform public._require_admin(); if p_bucket not in ('day', 'week', 'month') then raise exception 'invalid bucket' using errcode = '22023'; end if; return query select date_trunc(p_bucket, p.paid_at at time zone 'Asia/Tehran')::date, count(*), coalesce(sum(p.amount), 0)::bigint from public.payments p where p.status = 'paid' and (p.paid_at at time zone 'Asia/Tehran')::date between p_from and p_to group by 1 order by 1; end $$; create or replace function public.admin_set_user_role(p_user uuid, p_role public.app_role, p_grant boolean) returns void language plpgsql security definer set search_path = public as $$ begin perform public._require_admin(); if p_grant then insert into public.user_roles (user_id, role) values (p_user, p_role) on conflict (user_id, role) do nothing; else if p_role = 'admin' then if p_user = auth.uid() then raise exception 'cannot remove your own admin role' using errcode = '22023'; end if; if (select count(*) from public.user_roles where role = 'admin') <= 1 then raise exception 'cannot remove the last admin' using errcode = '22023'; end if; end if; delete from public.user_roles where user_id = p_user and role = p_role; end if; end $$; -- execute privileges revoke all on function public._mark_paid(uuid, uuid), public._release_payment(uuid, public.payment_status, uuid, text) from public, anon, authenticated; revoke all on function public.gateway_mark_paid(uuid, text, text), public.gateway_mark_failed(uuid) from public, anon, authenticated; grant execute on function public.gateway_mark_paid(uuid, text, text), public.gateway_mark_failed(uuid) to service_role; revoke all on function public.quote_cart(jsonb, text), public.create_checkout(jsonb, text, public.payment_method), public.submit_card_receipt(uuid, text, text, text), public.cancel_payment(uuid), public.get_checkout_options(), public.claim_referral(text), public.my_referral_summary() from public, anon; grant execute on function public.quote_cart(jsonb, text), public.create_checkout(jsonb, text, public.payment_method), public.submit_card_receipt(uuid, text, text, text), public.cancel_payment(uuid), public.get_checkout_options(), public.claim_referral(text), public.my_referral_summary() to authenticated; revoke all on function public.admin_review_payment(uuid, boolean, text), public.admin_set_secret(text, text), public.admin_secret_status(), public.admin_system_status(), public.admin_sales_summary(date, date, text), public.admin_set_user_role(uuid, public.app_role, boolean) from public, anon; grant execute on function public.admin_review_payment(uuid, boolean, text), public.admin_set_secret(text, text), public.admin_secret_status(), public.admin_system_status(), public.admin_sales_summary(date, date, text), public.admin_set_user_role(uuid, public.app_role, boolean) to authenticated; revoke all on function public.get_public_reviews(uuid, int), public.bot_rating_summary(uuid) from public; grant execute on function public.get_public_reviews(uuid, int), public.bot_rating_summary(uuid) to anon, authenticated; -- ===================== public site settings allow-list ===================== -- Public-readable keys: general (unchanged), toggles (booleans only), trust_badge, home_stats, seo. create or replace function public.is_public_site_setting(setting_key text, setting_value jsonb) returns boolean language sql immutable set search_path to 'public' as $$ select coalesce( case when jsonb_typeof(setting_value) <> 'object' then false else case setting_key when 'general' then setting_value - array['hero_title_fa','hero_title_en','hero_desc_fa','hero_desc_en','about_fa','about_en','telegram_support','telegram_channel','email','instagram','website']::text[] = '{}'::jsonb when 'toggles' then not exists (select 1 from jsonb_each(setting_value) e where jsonb_typeof(e.value) <> 'boolean') when 'trust_badge' then setting_value - array['href','image_url','alt_fa','alt_en','code']::text[] = '{}'::jsonb and coalesce(setting_value->>'href', '') ~ '^(https://[^[:space:]]+)?$' and coalesce(setting_value->>'image_url', '') ~ '^(https://[^[:space:]]+)?$' and coalesce(setting_value->>'code', '') ~ '^[A-Za-z0-9_-]{0,80}$' and coalesce(jsonb_typeof(setting_value->'alt_fa'), 'string') = 'string' and coalesce(jsonb_typeof(setting_value->'alt_en'), 'string') = 'string' when 'home_stats' then setting_value - array['show_bots','show_customers','show_support','customers_count']::text[] = '{}'::jsonb and coalesce(jsonb_typeof(setting_value->'show_bots'), 'boolean') = 'boolean' and coalesce(jsonb_typeof(setting_value->'show_customers'), 'boolean') = 'boolean' and coalesce(jsonb_typeof(setting_value->'show_support'), 'boolean') = 'boolean' and (case when jsonb_typeof(setting_value->'customers_count') is null then true when jsonb_typeof(setting_value->'customers_count') = 'number' then (setting_value #>> '{customers_count}')::numeric between 0 and 100000000 else false end) when 'seo' then setting_value - array['site_name_fa','site_name_en','description_fa','description_en','og_image']::text[] = '{}'::jsonb and coalesce(jsonb_typeof(setting_value->'site_name_fa'), 'string') = 'string' and coalesce(jsonb_typeof(setting_value->'site_name_en'), 'string') = 'string' and coalesce(jsonb_typeof(setting_value->'description_fa'), 'string') = 'string' and coalesce(jsonb_typeof(setting_value->'description_en'), 'string') = 'string' and char_length(coalesce(setting_value->>'description_fa', '')) <= 400 and char_length(coalesce(setting_value->>'description_en', '')) <= 400 and coalesce(setting_value->>'og_image', '') ~ '^(https://[^[:space:]]+)?$' else false end end, false); $$; -- ===================== seeds (do nothing if present) ===================== insert into public.private_settings (key, value) values ('card_to_card', '{"enabled": false, "cards": [], "instructions_fa": "", "instructions_en": ""}'::jsonb), ('gateway', '{"enabled": false, "provider": "zarinpal", "sandbox": false}'::jsonb), ('referral', '{"enabled": false, "kind": "percent", "value": 10, "expires_days": 90}'::jsonb), ('notify', '{"enabled": false, "chat_id": "", "events": {"order": true, "payment": true, "ticket": true, "review": true}}'::jsonb), ('memorial', '{"text_fa": "", "text_en": ""}'::jsonb) on conflict (key) do nothing; insert into public.site_settings (key, value, updated_at) values ('toggles', '{}'::jsonb, now()), ('trust_badge', '{"href": "", "image_url": "", "alt_fa": "", "alt_en": "", "code": ""}'::jsonb, now()), ('home_stats', '{"show_bots": true, "show_customers": false, "customers_count": 0, "show_support": true}'::jsonb, now()), ('seo', '{"site_name_fa": "SK Team", "site_name_en": "SK Team", "description_fa": "", "description_en": "", "og_image": ""}'::jsonb, now()) on conflict (key) do nothing; -- ===================== receipts storage (private) ===================== insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('receipts', 'receipts', false, 5242880, array['image/jpeg', 'image/png', 'image/webp']) on conflict (id) do update set public = false, file_size_limit = 5242880, allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']; drop policy if exists "users upload own receipts" on storage.objects; create policy "users upload own receipts" on storage.objects for insert to authenticated with check (bucket_id = 'receipts' and (storage.foldername(name))[1] = auth.uid()::text); drop policy if exists "users read own receipts" on storage.objects; create policy "users read own receipts" on storage.objects for select to authenticated using (bucket_id = 'receipts' and (storage.foldername(name))[1] = auth.uid()::text); drop policy if exists "admin reads all receipts" on storage.objects; create policy "admin reads all receipts" on storage.objects for select to authenticated using (bucket_id = 'receipts' and public.has_role(auth.uid(), 'admin'::public.app_role));